import{_ as a,o as e,c as o,a5 as r}from"./chunks/framework.Bt0SrEfo.js";const c=JSON.parse('{"title":"项目经验挂钩:简历怎么讲性能亮点","description":"","frontmatter":{},"headers":[],"relativePath":"performance/23-project-tie-in.md","filePath":"performance/23-project-tie-in.md","lastUpdated":1790007753000}'),l={name:"performance/23-project-tie-in.md"};function i(s,t,n,h,u,d){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="项目经验挂钩-简历怎么讲性能亮点" tabindex="-1">项目经验挂钩:简历怎么讲性能亮点 <a class="header-anchor" href="#项目经验挂钩-简历怎么讲性能亮点" aria-label="Permalink to &quot;项目经验挂钩:简历怎么讲性能亮点&quot;">​</a></h1><blockquote><p>面试时被问&quot;做过哪些性能优化&quot;,怎么答才有说服力? 本文按 4 个简历项目整理&quot;性能亮点 + 量化数据 + 面试表达模板&quot;。</p></blockquote><h2 id="一、商户管理-saas-平台" tabindex="-1">一、商户管理 SaaS 平台 <a class="header-anchor" href="#一、商户管理-saas-平台" aria-label="Permalink to &quot;一、商户管理 SaaS 平台&quot;">​</a></h2><h3 id="_1-1-接口契约-统一请求层" tabindex="-1">1.1 接口契约 + 统一请求层 <a class="header-anchor" href="#_1-1-接口契约-统一请求层" aria-label="Permalink to &quot;1.1 接口契约 + 统一请求层&quot;">​</a></h3><p><strong>做了什么</strong>:封装 axios + TypeScript 接口契约,统一错误处理、token 刷新、上报。</p><p><strong>性能/效率收益</strong>:</p><ul><li>字段变化导致的 bug 减少 60%(TypeScript 在编译期拦截)</li><li>接口响应失败自动重试,减少 30% 临时性失败报错</li><li>统一 token 刷新逻辑,登录失效不再导致 toast 轰炸</li></ul><p><strong>怎么讲</strong>:</p><blockquote><p>&quot;我做了一个统一请求层,封装了 axios + TS 接口契约 + 自动 token 刷新 + 错误上报。 上线后,因字段变化引起的 bug 减少 60%,前端定位问题的平均时间从 1 小时降到 10 分钟。&quot;</p></blockquote><h3 id="_1-2-dompurify-富文本安全" tabindex="-1">1.2 DOMPurify 富文本安全 <a class="header-anchor" href="#_1-2-dompurify-富文本安全" aria-label="Permalink to &quot;1.2 DOMPurify 富文本安全&quot;">​</a></h3><p><strong>做了什么</strong>:统一用 DOMPurify 过滤富文本,白名单 + 服务端二次校验。</p><p><strong>性能/安全收益</strong>:</p><ul><li>富文本类线上事故 0 起(过去一年)</li><li>服务端二次校验,即使前端绕过也安全</li></ul><p><strong>怎么讲</strong>:</p><blockquote><p>&quot;商户有自定义表单需求,涉及富文本。我引入 DOMPurify 做白名单过滤,服务端二次校验。 上线一年,富文本相关 XSS 事故 0 起。&quot;</p></blockquote><h3 id="_1-3-登录失效单点处理" tabindex="-1">1.3 登录失效单点处理 <a class="header-anchor" href="#_1-3-登录失效单点处理" aria-label="Permalink to &quot;1.3 登录失效单点处理&quot;">​</a></h3><p><strong>做了什么</strong>:拦截 401,统一发起 token 刷新,避免多个请求并发时多次触发登录。</p><p><strong>性能/体验收益</strong>:</p><ul><li>用户被强制登出次数下降 80%</li><li>关键流程(支付、提交)的成功率提升 15%</li></ul><h2 id="二、会员-web-h5" tabindex="-1">二、会员 Web / H5 <a class="header-anchor" href="#二、会员-web-h5" aria-label="Permalink to &quot;二、会员 Web / H5&quot;">​</a></h2><h3 id="_2-1-pwa-service-worker-弱网体验" tabindex="-1">2.1 PWA + Service Worker 弱网体验 <a class="header-anchor" href="#_2-1-pwa-service-worker-弱网体验" aria-label="Permalink to &quot;2.1 PWA + Service Worker 弱网体验&quot;">​</a></h3><p><strong>做了什么</strong>:注册 Service Worker,缓存关键资源(app shell + 静态资源)。</p><p><strong>性能收益</strong>:</p><ul><li>弱网(2G/3G)下首屏时间从 8s 降到 3s</li><li>完全离线时仍可访问已访问过的页面</li><li>Lighthouse PWA 评分 100</li></ul><p><strong>怎么讲</strong>:</p><blockquote><p>&quot;我们对会员 H5 做了 PWA 改造,核心策略是用 Service Worker 缓存 app shell。 弱网(2G)用户首屏时间从 8s 降到 3s,Lighthouse PWA 评分 100。&quot;</p></blockquote><h3 id="_2-2-app-通信三通道冗余" tabindex="-1">2.2 App 通信三通道冗余 <a class="header-anchor" href="#_2-2-app-通信三通道冗余" aria-label="Permalink to &quot;2.2 App 通信三通道冗余&quot;">​</a></h3><p><strong>做了什么</strong>:与 Native App 通信时,同时建立 WebSocket / postMessage / URL Scheme 三个通道,任一失败自动切换。</p><p><strong>稳定性收益</strong>:</p><ul><li>通信成功率从 96% 提升到 99.8%</li><li>关键路径(支付回调、登录态)失败率 &lt; 0.1%</li></ul><h3 id="_2-3-多端适配" tabindex="-1">2.3 多端适配 <a class="header-anchor" href="#_2-3-多端适配" aria-label="Permalink to &quot;2.3 多端适配&quot;">​</a></h3><p><strong>做了什么</strong>:rem 适配 + vw/vh 单位 + 关键场景用 vh 兜底 iOS Safari 工具栏高度变化。</p><p><strong>体验收益</strong>:</p><ul><li>跨设备(iOS/Android/不同尺寸)布局一致性问题减少 70%</li></ul><h2 id="三、智能风控引擎平台" tabindex="-1">三、智能风控引擎平台 <a class="header-anchor" href="#三、智能风控引擎平台" aria-label="Permalink to &quot;三、智能风控引擎平台&quot;">​</a></h2><h3 id="_3-1-vue-2-→-vue-3-vite-迁移" tabindex="-1">3.1 Vue 2 → Vue 3 + Vite 迁移 <a class="header-anchor" href="#_3-1-vue-2-→-vue-3-vite-迁移" aria-label="Permalink to &quot;3.1 Vue 2 → Vue 3 + Vite 迁移&quot;">​</a></h3><p><strong>做了什么</strong>:完整迁移 Webpack → Vite + Vue 2 → Vue 3 + Composition API。</p><p><strong>核心数据</strong>:</p><table tabindex="0"><thead><tr><th>指标</th><th>改前</th><th>改后</th></tr></thead><tbody><tr><td>冷启动</td><td>30s+</td><td>&lt; 1s</td></tr><tr><td>首屏 JS</td><td>5.94 MiB</td><td>3.92 MiB(-34%)</td></tr><tr><td>Lighthouse</td><td>41</td><td>92</td></tr><tr><td>增量构建</td><td>8s+</td><td>&lt; 500ms</td></tr></tbody></table><h3 id="_3-2-element-plus-echarts-按需引入" tabindex="-1">3.2 Element Plus / ECharts 按需引入 <a class="header-anchor" href="#_3-2-element-plus-echarts-按需引入" aria-label="Permalink to &quot;3.2 Element Plus / ECharts 按需引入&quot;">​</a></h3><p><strong>做了什么</strong>:从全量引入改为按需引入,自动注册。</p><p><strong>收益</strong>:</p><ul><li>element-plus 从 1.8MB → 380KB</li><li>echarts 从 2.4MB → 420KB</li><li>首屏直接下降 2MB+</li></ul><h3 id="_3-3-规则引擎可视化" tabindex="-1">3.3 规则引擎可视化 <a class="header-anchor" href="#_3-3-规则引擎可视化" aria-label="Permalink to &quot;3.3 规则引擎可视化&quot;">​</a></h3><p><strong>做了什么</strong>:运营可以通过拖拽配置规则,不需要研发改代码。</p><p><strong>效率收益</strong>:</p><ul><li>新规则上线时间从 2 天 → 2 小时</li><li>运营自助配置占比 60%</li></ul><h2 id="四、农业数字化-app-iot-大屏" tabindex="-1">四、农业数字化 App + IoT 大屏 <a class="header-anchor" href="#四、农业数字化-app-iot-大屏" aria-label="Permalink to &quot;四、农业数字化 App + IoT 大屏&quot;">​</a></h2><h3 id="_4-1-定时器清理" tabindex="-1">4.1 定时器清理 <a class="header-anchor" href="#_4-1-定时器清理" aria-label="Permalink to &quot;4.1 定时器清理&quot;">​</a></h3><p><strong>做了什么</strong>:在 Vue 组件 <code>beforeUnmount</code> 钩子统一清理 setInterval / setTimeout。</p><p><strong>实测收益</strong>:</p><ul><li>IoT 大屏连续运行 24 小时,内存增长 &lt; 50MB</li><li>不清理时,内存增长 200~500MB/24h</li></ul><p><strong>怎么讲</strong>:</p><blockquote><p>&quot;IoT 大屏要 7x24 小时运行,定时器未清理会让内存持续增长。我加了统一的清理钩子, 连续运行 24 小时,内存增长从 500MB 降到 50MB,基本稳定。&quot;</p></blockquote><h3 id="_4-2-异步-tooltip" tabindex="-1">4.2 异步 tooltip <a class="header-anchor" href="#_4-2-异步-tooltip" aria-label="Permalink to &quot;4.2 异步 tooltip&quot;">​</a></h3><p><strong>做了什么</strong>:ECharts tooltip 默认是同步渲染,数据量大时卡顿。改为异步:鼠标移入 100ms 后才请求/渲染。</p><p><strong>收益</strong>:</p><ul><li>大数据(10000 点)hover 延迟从 200ms 降到 50ms</li><li>滚动 FPS 60 稳定</li></ul><h3 id="_4-3-echarts-实例-dispose" tabindex="-1">4.3 ECharts 实例 dispose <a class="header-anchor" href="#_4-3-echarts-实例-dispose" aria-label="Permalink to &quot;4.3 ECharts 实例 dispose&quot;">​</a></h3><p><strong>做了什么</strong>:路由切换前必须 dispose ECharts 实例,否则 canvas 内存不释放。</p><p><strong>收益</strong>:</p><ul><li>路由切换 100 次后,内存增长 &lt; 30MB</li><li>不 dispose 时,内存增长 500MB+</li></ul><h2 id="五、面试通用表达模板" tabindex="-1">五、面试通用表达模板 <a class="header-anchor" href="#五、面试通用表达模板" aria-label="Permalink to &quot;五、面试通用表达模板&quot;">​</a></h2><h3 id="_5-1-star-法则" tabindex="-1">5.1 STAR 法则 <a class="header-anchor" href="#_5-1-star-法则" aria-label="Permalink to &quot;5.1 STAR 法则&quot;">​</a></h3><p>每个性能优化都可以套:</p><ul><li><strong>S</strong>ituation:当时的问题(用户投诉 / 老板要求 / 监控告警)</li><li><strong>T</strong>ask:目标(降到 X 秒 / 提升 Y%)</li><li><strong>A</strong>ction:你做了什么(技术选型 + 实现)</li><li><strong>R</strong>esult:量化收益(数字 + 对比)</li></ul><h3 id="_5-2-反例-流水账" tabindex="-1">5.2 反例:流水账 <a class="header-anchor" href="#_5-2-反例-流水账" aria-label="Permalink to &quot;5.2 反例:流水账&quot;">​</a></h3><blockquote><p>❌ &quot;我做了 Webpack 到 Vite 的迁移,优化了首屏。&quot;——太空洞,没数字。</p></blockquote><h3 id="_5-3-正例-有数据有对比" tabindex="-1">5.3 正例:有数据有对比 <a class="header-anchor" href="#_5-3-正例-有数据有对比" aria-label="Permalink to &quot;5.3 正例:有数据有对比&quot;">​</a></h3><blockquote><p>✅ &quot;我们风控平台冷启动 30s+,老板要求降到 3s 内。我做了 Webpack→Vite 迁移,Element Plus / ECharts 按需引入, 路由拆包。冷启动从 30s+ 降到 &lt; 1s,首屏 JS 从 5.94MB 降到 3.92MB,Lighthouse 从 41 升到 92。&quot;——具体、有数字、有影响。</p></blockquote><h3 id="_5-4-数字怎么记" tabindex="-1">5.4 数字怎么记 <a class="header-anchor" href="#_5-4-数字怎么记" aria-label="Permalink to &quot;5.4 数字怎么记&quot;">​</a></h3><p>工作中<strong>随时记录数据</strong>,面试前整理:</p><ul><li>改前基线(任何能拿到的)</li><li>改后数据</li><li>持续时长(避免&quot;上线一年数据好看&quot;——面试官可能问&quot;为啥半年后不行了?&quot;)</li></ul><h2 id="六、常见追问准备" tabindex="-1">六、常见追问准备 <a class="header-anchor" href="#六、常见追问准备" aria-label="Permalink to &quot;六、常见追问准备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>追问</th><th>准备</th></tr></thead><tbody><tr><td>&quot;为什么选 Vite 而非 Webpack 5?&quot;</td><td>见 24-real-project 选型过程</td></tr><tr><td>&quot;有没有负作用?&quot;</td><td>没有功能回归,但团队需要适应 Vue 3 写法,给了 2 周过渡期</td></tr><tr><td>&quot;如果再做一次,会怎么做?&quot;</td><td>先做 SSR Streaming 再迁 Vite,可以叠加收益</td></tr><tr><td>&quot;如何避免优化后又退化?&quot;</td><td>接 Lighthouse CI + RUM 监控告警</td></tr></tbody></table><h2 id="七、参考文献" tabindex="-1">七、参考文献 <a class="header-anchor" href="#七、参考文献" aria-label="Permalink to &quot;七、参考文献&quot;">​</a></h2><ul><li><a href="https://en.wikipedia.org/wiki/Situation,_task,_action,_result" target="_blank" rel="noreferrer">STAR 法则</a></li></ul>',77)])])}const q=a(l,[["render",i]]);export{c as __pageData,q as default};
